<div class="section-title"><h2>Document catalog</h2><a class="button primary" href="index.php?page=documents&add=1#document-form">Add Document</a></div>
<section class="panel table-scroll"><table><thead><tr><th>Document</th><th>Description</th><th>Fee (PHP)</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM documents ORDER BY name') as $doc): ?><tr><td><?= e($doc['name']) ?></td><td><?= e($doc['description']) ?></td><td><?= e(number_format((float)$doc['fee'],2)) ?></td><td><span class="badge"><?= $doc['is_active']?'Active':'Inactive' ?></span></td><td><div class="button-row"><a class="button secondary compact" href="index.php?page=documents&edit=<?= (int)$doc['id'] ?>#document-form">Edit</a><form action="action.php" method="post" data-confirm="<?= $doc['is_active']?'Are you sure you want to deactivate?':'Are you sure you want to activate?' ?>"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $doc['is_active']?'deactivate':'activate' ?>"><input type="hidden" name="id" value="<?= (int)$doc['id'] ?>"><button class="button secondary compact"><?= $doc['is_active']?'Deactivate':'Activate' ?></button></form><form action="action.php" method="post" data-confirm="Are you sure you want to delete?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$doc['id'] ?>"><button class="button danger compact">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></section>
<?php
$edit=query_input('edit'); $doc=ctype_digit($edit)?(rows('SELECT * FROM documents WHERE id=?',[(int)$edit])[0]??null):null;
if(isset($_GET['add'])||$doc): ?>
<section class="panel dashboard-actions" id="document-form"><h2><?= $doc?'Edit document':'Add document' ?></h2><?php action_form('save_document'); ?><input type="hidden" name="id" value="<?= e($doc['id']??'') ?>"><div class="form-stack"><label>Document Name<input name="name" maxlength="150" required value="<?= e($doc['name']??'') ?>"></label><?php foreach(['description'=>'Description','purpose'=>'Purpose','requirements'=>'Requirements'] as $field=>$label): ?><label><?= e($label) ?><textarea name="<?= e($field) ?>" maxlength="<?= $field==='purpose'?5000:10000 ?>" required><?= e($doc[$field]??'') ?></textarea></label><?php endforeach; ?><div class="form-grid"><label>Fee (PHP)<input type="number" name="fee" min="0" max="99999999.99" step="0.01" required value="<?= e($doc['fee']??'0.00') ?>"></label><label>Processing time<input name="processing_time" maxlength="150" required value="<?= e($doc['processing_time']??'1–2 working days') ?>"></label></div><button class="button primary"><?= $doc?'Save changes':'Add Document' ?></button></div></form></section><?php endif; ?>
